fn acquire(pool: &Pool, tenant: &str) -> Result<Session, PoolError> {
    if tenant.is_empty() {
        return Err(PoolError::BadTenant);       // reject before touching state
    }
    let slot = pool.try_acquire(tenant)?;       // propagate immediately
    Ok(Session::new(slot))                      // Drop releases it on any later error
}
